        submitEnv("G-SPEC", "10", "0", "10.25", "25", "50", "0.05");
        // 不确定度 0.2 > 0.1 → UNCERTAINTY_EXCEEDED（补偿值合格）
        submitEnv("G-UNC", "10", "10.2", "10.4", "25", "50", "0.2");

        releaseGate(List.of("G-SPEC", "G-UNC"), "0.1", "carol")
