        long v2 = createProfile("MODEL-A", "0.02", "0.002");          // 新版本
        submitEnv("NEW", "10", "0", "99", "25", "50", "0.05");          // 10 + 0.5 + 0.1 = 10.600000 @ v2

        mvc.perform(get("/api/measurements/{key}", "OLD"))
